#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "floyd-warshall.h"

/* ------------------------------------------------------------------------
 * Tunable tiling parameters.
 *
 * These control the i/j blocking sizes used in the main kernel.  They are
 * chosen so that a T_I × T_J tile of `path` comfortably fits in L1/L2 cache
 * alongside the per‑k snapshots of row k and column k.
 *
 * You may adjust these at compile time by defining T_I / T_J.
 * ------------------------------------------------------------------------ */
#ifndef T_I
# define T_I 32
#endif

#ifndef T_J
# define T_J 32
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      path[i][j] = i*j%7+1;
      if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
         path[i][j] = 999;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("path");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, path[i][j]);
    }
  POLYBENCH_DUMP_END("path");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:

   - For each k, we take *snapshots* of row k and column k of `path` into
     temporary 1D arrays row_k[] and col_k[].  These snapshots are taken
     at the beginning of the k-th stage and are then read-only.
       * This implements the standard Floyd–Warshall DP recurrence
         D^{k+1}[i,j] = min(D^{k}[i,j], D^{k}[i,k] + D^{k}[k,j])
         using explicit per‑k buffers.
       * For the PolyBench initialization, all entries are >= 1 or 999,
         so path[i][k] and path[k][j] never decrease during a fixed-k
         sweep, and this snapshot-based formulation produces the same
         result as the original in-place k–i–j triple loop.

   - With snapshots, all (i, j) updates at fixed k are independent.
     We exploit this by:
       * Blocking (tiling) the i and j loops for better cache locality.
       * Hoisting col_k[i] out of the innermost j-loop so it can stay in
         a register across the tile.
       * Using contiguous pointers in the innermost loop to enable the
         compiler to generate SIMD code easily.

   The overall asymptotic complexity remains O(N^3); only constants and
   memory-access patterns are improved.
*/
static
void kernel_floyd_warshall[[gnu::flatten, gnu::noinline]](int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

  /* Per‑k snapshots of row k and column k.
     Size uses the PolyBench loop bound macro so that the buffers match
     the effective iteration space of the kernel. */
  DATA_TYPE row_k[_PB_N];
  DATA_TYPE col_k[_PB_N];

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      /* Snapshot row k and column k at the start of this k-iteration.
         These correspond to D^{k}[k, *] and D^{k}[*, k] in the classical
         Floyd–Warshall DP formulation. */
      for (j = 0; j < _PB_N; j++)
        row_k[j] = path[k][j];

      for (i = 0; i < _PB_N; i++)
        col_k[i] = path[i][k];

      /* 2D blocking of the (i, j) space for cache efficiency.  We keep
         k outermost and sequential (DP along k), and work on T_I × T_J
         tiles of the `path` matrix per k-stage. */
      for (int ii = 0; ii < _PB_N; ii += T_I)
      {
        int i_end = ii + T_I;
        if (i_end > _PB_N)
          i_end = _PB_N;

        for (i = ii; i < i_end; i++)
        {
          /* col_k[i] is invariant across the inner j-loop for fixed (k, i).
             Load it once so the compiler can keep it in a register. */
          const DATA_TYPE col_ik = col_k[i];

          /* Process j in tiles to work on contiguous sub-rows of path[i][*]
             together with the corresponding slice of row_k[]. */
          for (int jj = 0; jj < _PB_N; jj += T_J)
          {
            int j_end = jj + T_J;
            if (j_end > _PB_N)
              j_end = _PB_N;

            /* Pointers to the current tiles of `path` row i and row_k.
               Both are contiguous over the upcoming inner loop, which
               greatly helps auto-vectorization. */
            DATA_TYPE * restrict path_row    = &path[i][jj];
            DATA_TYPE * restrict row_k_tile  = &row_k[jj];
            const int tile_width = j_end - jj;

            /* Inner j-loop over a single tile.  This implements:
                 path[i][j] = min(path[i][j], col_k[i] + row_k[j]);
               for j in [jj, j_end), but using pointers and a local
               index `t` to expose unit-stride memory accesses. */
            for (int t = 0; t < tile_width; t++)
            {
              const DATA_TYPE via_k = col_ik + row_k_tile[t];
              const DATA_TYPE cur   = path_row[t];
              path_row[t] = (cur < via_k) ? cur : via_k;
            }
          }
        }
      }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(path)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(path);

  return 0;
}
