   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("path");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, path[i][j]);
    }
  POLYBENCH_DUMP_END("path");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_floyd_warshall[[gnu::flatten, gnu::noinline]](int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

  /* Scratch buffers used to hold a snapshot of row k and column k
     at the beginning of each k-iteration.

     For the PolyBench initialization in init_array(), all entries
     of "path" are strictly positive (either in [1,7] or 999). In
     particular, the diagonal elements path[k][k] are > 0 for all k.

     In the original in-place Floyd–Warshall update

       path[i][j] = min(path[i][j], path[i][k] + path[k][j])

     this implies that during a fixed k-iteration the values
     path[i][k] and path[k][j] never decrease: using vertex k as
     an intermediate to reach k itself cannot shorten a path when
     path[k][k] > 0. Therefore, row k and column k are effectively
     invariant within the inner (i,j) loops at that k.

     Taking snapshots of row k and column k before updating the
     matrix is thus mathematically equivalent to reading path[i][k]
     and path[k][j] directly in the original code, while removing
     any loop-carried dependences across i and j for this kernel.
     This enables more aggressive tiling and vectorization. */
  DATA_TYPE row_k[_PB_N];
  DATA_TYPE col_k[_PB_N];

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      /* 1. Snapshot row k and column k from the beginning of this k-step. */
      for (j = 0; j < _PB_N; j++)
        row_k[j] = path[k][j];

      for (i = 0; i < _PB_N; i++)
        col_k[i] = path[i][k];

      /* 2. Tiled relaxation over (i, j).

         We work on TI×TJ tiles of the path matrix to improve cache
         locality. Within each tile, j is the innermost loop so that
         accesses to path[i][j] and row_k[j] are unit-stride in memory,
         which helps the compiler generate SIMD code. */
      const int ti = FLOYD_WARSHALL_BLOCK_I;
      const int tj = FLOYD_WARSHALL_BLOCK_J;

      int ii, jj;
      for (ii = 0; ii < _PB_N; ii += ti)
        {
          int i_end = ii + ti;
          if (i_end > _PB_N)
            i_end = _PB_N;

          for (jj = 0; jj < _PB_N; jj += tj)
            {
              int j_end = jj + tj;
              if (j_end > _PB_N)
                j_end = _PB_N;

              const int j_len = j_end - jj;
              DATA_TYPE *row_k_tile = &row_k[jj];

              for (i = ii; i < i_end; i++)
                {
                  /* Hoist col_k[i] and the base pointer for the
                     current row tile of 'path' out of the inner j-loop
                     to reduce redundant address computation and loads. */
                  DATA_TYPE col_i = col_k[i];
                  DATA_TYPE *restrict path_row = &path[i][jj];

                  /* Innermost loop: contiguous in memory and free of
                     loop-carried dependences, suitable for SIMD. */
#pragma GCC ivdep
                  for (int t = 0; t < j_len; t++)
                    {
                      DATA_TYPE cand    = col_i + row_k_tile[t];
                      DATA_TYPE current = path_row[t];
                      path_row[t] = (current < cand) ? current : cand;
                    }
                }
            }
        }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

