  const int tile_j = 32;

  /* Per-k snapshots of column k and row k.
     We use 'n' (the runtime problem size).  PolyBench guarantees
     that 0 <= i,j,k < _PB_N and _PB_N <= n, so these buffers are
     always large enough for all loop bounds. */
