         of this k-iteration.  Accesses are stride-1 in 'i' because
         col_k is a 1D array. */
      for (i = 0; i < _PB_N; i++)
        col_k[i] = path[i][k];

      /* Snapshot row k: row_k[j] = path[k][j].  This is also a
         contiguous read from memory, improving spatial locality. */
      for (j = 0; j < _PB_N; j++)
        row_k[j] = path[k][j];

      /* 2D tiling (blocking) over the (i, j) space.  This improves
         temporal locality for the submatrix of "path" being updated
         while reusing the snapshot row_k[] and col_k[]. */
      for (I = 0; I < _PB_N; I += tile_i)
        {
          int i_max = I + tile_i;
          if (i_max > _PB_N)
            i_max = _PB_N;

          for (J = 0; J < _PB_N; J += tile_j)
            {
              int j_max = J + tile_j;
              if (j_max > _PB_N)
                j_max = _PB_N;

              for (i = I; i < i_max; i++)
                {
                  /* Hoist the column value used for this entire row
                     of the tile; this reduces one load per inner
                     iteration and keeps it in a register. */
                  DATA_TYPE col_ik = col_k[i];

                  /* Innermost loop over j:
                     - accesses path[i][j] with unit stride,
                     - accesses row_k[j] with unit stride,
                     which is ideal for auto-vectorization. */
