                  for (j = J; j < j_max; j++)
                    {
                      DATA_TYPE new_dist = col_ik + row_k[j];
                      DATA_TYPE current  = path[i][j];
                      /* Branchless minimum; for floating-point
                         DATA_TYPE this corresponds to the usual
                         arithmetic min on the finite values used
                         in this benchmark. */
                      path[i][j] = (current < new_dist) ? current : new_dist;
                    }
                }
            }
        }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
