        i_max = _PB_N;

      for (i = ii; i < i_max; i++)
      {
        DATA_TYPE* row_i = path[i];

        /* As explained above, path[i][k] is invariant within this k-step,
         * so we can hoist it once per (k, i) and keep it in a register.
         */
        DATA_TYPE path_ik = row_i[k];

        /* Block columns (j-dimension).  Since the matrix is row-major,
         * j is the stride-1 dimension; keeping j innermost preserves
         * unit-stride accesses and enables efficient SIMD vectorization.
         */
        for (int jj = 0; jj < _PB_N; jj += TJ)
        {
          int j_max = jj + TJ;
          if (j_max > _PB_N)
            j_max = _PB_N;

          /* Innermost j-loop: contiguous accesses to row_i[j] and row_k[j].
           * The explicit, branchless min maps well to SIMD:
           *   new = (via_k < current) ? via_k : current;
           */
          for (j = jj; j < j_max; j++)
          {
            DATA_TYPE via_k   = path_ik + row_k[j];
            DATA_TYPE current = row_i[j];
            row_i[j] = (via_k < current) ? via_k : current;
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(path)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(path);

  return 0;
