/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("path");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, path[i][j]);
    }
  POLYBENCH_DUMP_END("path");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Keep k as the outer, sequential DP loop (Floyd–Warshall semantics).
 *  - Block (tile) the i and j dimensions to improve cache locality.
 *  - For each (k, i), hoist path[i][k] into a scalar (register) since it is
 *    invariant across j in that iteration.
 *  - Access rows via explicit row pointers (row-major friendly).
 *  - Inner-most loop is over j (contiguous in memory) to enable auto-SIMD.
 *  - Optional OpenMP parallelization over i-tiles (rows) for each k; if the
 *    code is compiled without -fopenmp, the pragmas are ignored.
 *
 * Correctness note:
 *  - init_array initializes all edge weights to positive values (1..7) or 999.
 *    Therefore all path[i][j] remain non-negative and, in particular,
 *    path[k][k] >= 0 for all k during the computation.
 *  - Under this condition, entries in row k and column k are not improved
 *    inside the k-th outer iteration, so path[i][k] and path[k][j] are
 *    effectively constant for fixed k. This makes all (i, j) updates at a
 *    given k independent and allows tiling and parallelization in i, j
 *    without changing the numerical result.
 */
static
void kernel_floyd_warshall[[gnu::flatten, gnu::noinline]](int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

  /* Tile sizes chosen to keep a TI×TJ tile of 'path' in cache together with
     the k-th row. These can be tuned for a given machine. */
  const int TI = 32;
  const int TJ = 32;

#pragma scop
  /* Outer dynamic-programming loop over allowed intermediate vertex k. */
  for (k = 0; k < _PB_N; k++)
    {
      /* Pointer to row k (path[k][*]), used heavily inside this k-iteration. */
      DATA_TYPE * restrict row_k = path[k];

      /* Parallelize across bands of rows (i-tiles) for this fixed k.
         Each iteration of the 'ii' loop works on a distinct set of rows,
         so there are no write–write races between threads. */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) private(i, j) firstprivate(row_k, k) if (_PB_N >= 64)
#endif
      for (int ii = 0; ii < _PB_N; ii += TI)
        {
          int i_end = ii + TI;
          if (i_end > _PB_N)
            i_end = _PB_N;

          /* Iterate over column tiles inside this band of rows. */
          for (int jj = 0; jj < _PB_N; jj += TJ)
            {
              int j_end = jj + TJ;
              if (j_end > _PB_N)
                j_end = _PB_N;

              /* Process rows in [ii, i_end) for columns in [jj, j_end). */
              for (i = ii; i < i_end; i++)
                {
                  DATA_TYPE * restrict row_i = path[i];

                  /* For fixed (k, i), path[i][k] is invariant across all j
                     in this k-iteration, so load it once into a scalar. */
                  DATA_TYPE path_ik = row_i[k];

                  /* Inner-most loop over contiguous j: good spatial locality
                     for both row_i[j] and row_k[j], and enables SIMD. */
                  for (j = jj; j < j_end; j++)
                    {
                      DATA_TYPE via_k = path_ik + row_k[j];
                      DATA_TYPE current = row_i[j];
                      row_i[j] = (current < via_k) ? current : via_k;
                    }
                }
            }
        }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
